import re, collections
data = open('/usr/local/lib/python3.13/site-packages/mujoco/plugin/libelasticity.so','rb').read()
strs = [s.decode('latin1') for s in re.findall(rb'_Z[A-Za-z0-9_]+', data)]
names = sorted(set(strs))
# Collect readable words from ALL mangled names, weighted
allw = collections.Counter()
for n in names:
    for w in re.findall(r'[A-Za-z_][A-Za-z0-9_]{2,}', n):
        allw[w]+=1
# print most common, excluding generic C++ noise
noise = {'std','string','char','void','const','int','float','double','size','unsigned','long','short','bool','wchar','allocator','__1','vector','map','list','array','pair','tuple','optional','unique','shared','weak','enable','shared_ptr','__ptr','__value','__end','__begin','__size','__cap','__alloc','__node','__impl','__detail','__shared','__weak','__compressed','_M','_T','_T0','_T1','_T2'}
for w,c in allw.most_common(120):
    if w not in noise and not w.startswith('_') and not w.startswith('__'):
        print(w,c)
